/* ─── Reset / base ────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 100%; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* ─── Skip link ───────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 0;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  font-weight: 600;
  border-radius: 0 0 var(--radius-sm) 0;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:focus {
  top: 0;
  outline: 3px solid var(--color-primary-active);
  outline-offset: 2px;
}

/* ─── Header ──────────────────────────────────────────────────────── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}
.header-inner {
  max-width: 64rem;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
}
.logo {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: -.02em;
}

/* ─── Layout ──────────────────────────────────────────────────────── */
.page-container {
  max-width: 40rem;
  margin: 0 auto;
  padding: 2.5rem 1.5rem 4rem;
}

.page-eyebrow {
  display: block;
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: .5rem;
}

.page-title {
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -.025em;
  color: var(--color-text);
  margin-bottom: .5rem;
}

.page-desc {
  color: var(--color-text-muted);
  font-size: .9375rem;
  margin-bottom: 2rem;
}

/* ─── Card ────────────────────────────────────────────────────────── */
.form-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem;
}

/* ─── Required legend ─────────────────────────────────────────────── */
.required-note {
  font-size: .8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}
.required-marker { color: var(--color-error); font-weight: 700; }

/* ─── Form field wrapper ──────────────────────────────────────────── */
.form-field { margin-bottom: 1.75rem; }

/* ─── Fieldset / legend ───────────────────────────────────────────── */
.form-field fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.form-field legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 1.125rem;
  line-height: 1.4;
}

.legend-required {
  color: var(--color-error);
  margin-left: .125rem;
  font-weight: 700;
}

/* ─── Radio group ─────────────────────────────────────────────────── */
.radio-group {
  display: flex;
  flex-direction: column;
  gap: .625rem;
}

/* Each radio option row */
.radio-option {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .875rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color .15s, background .15s;
  position: relative;
}
.radio-option:hover {
  border-color: var(--color-primary);
  background: #eff6ff;
}

/* Whole-row click target via pseudo-element on the label */
.radio-option label {
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-text);
  cursor: pointer;
  flex: 1;
}
.radio-option label::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
}

/* Native radio — hidden visually but accessible */
.radio-option input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.125rem;
  height: 1.125rem;
  min-width: 1.125rem;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  background: var(--color-surface);
  cursor: pointer;
  position: relative;
  transition: border-color .15s;
  flex-shrink: 0;
}
.radio-option input[type="radio"]::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 50%;
  background: transparent;
  transition: background .15s;
}

/* Checked state */
.radio-option input[type="radio"]:checked {
  border-color: var(--color-radio-dot);
}
.radio-option input[type="radio"]:checked::after {
  background: var(--color-radio-dot);
}

/* Highlight the whole row when checked */
.radio-option:has(input[type="radio"]:checked) {
  border-color: var(--color-primary);
  background: #eff6ff;
}

/* Focus ring — 2px offset, high contrast */
.radio-option input[type="radio"]:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 2px;
}

/* Invalid state */
.radio-option input[type="radio"][aria-invalid="true"] {
  border-color: var(--color-error);
}

/* ─── Error message ───────────────────────────────────────────────── */
.error-message {
  display: flex;
  align-items: flex-start;
  gap: .4rem;
  margin-top: .75rem;
  padding: .625rem .875rem;
  background: var(--color-error-bg);
  border: 1px solid #fca5a5;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  color: var(--color-error);
  font-weight: 500;
}
.error-message[hidden] { display: none; }

/* ─── Submit button ───────────────────────────────────────────────── */
.form-actions { margin-top: .25rem; }

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: .75rem 1.75rem;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: #fff;
  background: var(--color-primary);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s, transform .1s;
  min-width: 10rem;
}
.btn-primary:hover { background: var(--color-primary-hover); }
.btn-primary:active { background: var(--color-primary-active); transform: scale(.98); }
.btn-primary:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 3px;
}

/* ─── Status banner ───────────────────────────────────────────────── */
.status-banner {
  display: flex;
  align-items: center;
  gap: .625rem;
  padding: .875rem 1.125rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}
.status-banner[hidden] { display: none; }
.status-banner--success {
  background: #f0fdf4;
  border: 1px solid #86efac;
  color: var(--color-success);
}
.status-banner__icon { font-size: 1.125rem; flex-shrink: 0; }

/* ─── Screen-reader only ──────────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ─── Forced / high-contrast colors ──────────────────────────────── */
@media (forced-colors: active) {
