.form-field fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.form-field legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 1.125rem;
  line-height: 1.4;
}

.legend-required {
  color: var(--color-error);
  margin-left: .125rem;
  font-weight: 700;
}

/* ─── Radio group ─────────────────────────────────────────────────── */
.radio-group {
  display: flex;
  flex-direction: column;
  gap: .625rem;
}

/* Each radio option row */
.radio-option {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .875rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color .15s, background .15s;
  position: relative;
}
.radio-option:hover {
  border-color: var(--color-primary);
  background: #eff6ff;
}

/* Whole-row click target via pseudo-element on the label */
.radio-option label {
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-text);
  cursor: pointer;
  flex: 1;
}
.radio-option label::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
}

