.radio-option input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.125rem;
  height: 1.125rem;
  min-width: 1.125rem;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  background: var(--color-surface);
  cursor: pointer;
  position: relative;
  transition: border-color .15s;
  flex-shrink: 0;
}
.radio-option input[type="radio"]::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 50%;
  background: transparent;
  transition: background .15s;
}

/* Checked state */
.radio-option input[type="radio"]:checked {
  border-color: var(--color-radio-dot);
}
.radio-option input[type="radio"]:checked::after {
  background: var(--color-radio-dot);
}

/* Highlight the whole row when checked */
.radio-option:has(input[type="radio"]:checked) {
  border-color: var(--color-primary);
  background: #eff6ff;
}

/* Focus ring — 2px offset, high contrast */
.radio-option input[type="radio"]:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 2px;
}

/* Invalid state */
.radio-option input[type="radio"][aria-invalid="true"] {
  border-color: var(--color-error);
}

/* ─── Error message ───────────────────────────────────────────────── */
.error-message {
  display: flex;
  align-items: flex-start;
  gap: .4rem;
  margin-top: .75rem;
  padding: .625rem .875rem;
  background: var(--color-error-bg);
  border: 1px solid #fca5a5;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  color: var(--color-error);
  font-weight: 500;
}
.error-message[hidden] { display: none; }

/* ─── Submit button ───────────────────────────────────────────────── */
.form-actions { margin-top: .25rem; }

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: .75rem 1.75rem;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: #fff;
  background: var(--color-primary);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s, transform .1s;
  min-width: 10rem;
}
.btn-primary:hover { background: var(--color-primary-hover); }
.btn-primary:active { background: var(--color-primary-active); transform: scale(.98); }
.btn-primary:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 3px;
}

/* ─── Status banner ───────────────────────────────────────────────── */
.status-banner {
  display: flex;
  align-items: center;
  gap: .625rem;
  padding: .875rem 1.125rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}
.status-banner[hidden] { display: none; }
.status-banner--success {
  background: #f0fdf4;
  border: 1px solid #86efac;
  color: var(--color-success);
}
.status-banner__icon { font-size: 1.125rem; flex-shrink: 0; }

/* ─── Screen-reader only ──────────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ─── Forced / high-contrast colors ──────────────────────────────── */
@media (forced-colors: active) {
  .radio-option { border-color: ButtonText; }
  .radio-option:hover,
  .radio-option:has(input[type="radio"]:checked) { border-color: Highlight; }
  .radio-option input[type="radio"] { forced-color-adjust: auto; }
  .btn-primary { forced-color-adjust: auto; }
}

/* ─── Reduced motion ──────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0s !important; }
}

/* ─── Reflow: 320 px ──────────────────────────────────────────────── */
@media (max-width: 360px) {
  .form-card { padding: 1.25rem 1rem; }
  .page-title { font-size: 1.375rem; }
}
